from PIL import Image, ImageEnhance
im = Image.open('radiograph.jpg').convert('L')
crops = {
 'raw_ul_blob': (1700, 480, 1900, 660, 4),
 'raw_ul_canine_apex': (1540, 330, 1760, 540, 4),
}
for name, (x1,y1,x2,y2,s) in crops.items():
    c = im.crop((x1,y1,x2,y2))
    c = ImageEnhance.Contrast(c.resize((int((x2-x1)*s), int((y2-y1)*s)), Image.LANCZOS)).enhance(1.25)
    c.save(f'/tmp/{name}.png')
    print(name, c.size)
EOF", "description": "Zoom upper left premolar-molar interdental dark spot"}

